import json,re
from itertools import groupby
def last_ans(s):
    m=re.findall(r'#### (-?[0-9.,]+)',s)
    return m[-1].replace(',','') if m else None
def ok(o,g):
    a=last_ans(o)
    if a is None:
        return False
    try:
        return abs(float(a)-float(g))<1e-6
    except Exception:
        return False
def run(o):
    return max((len(list(g)) for _,g in groupby(o)),default=0)
for kind in ('val_generations','rollouts'):
    for step in ((0,50,100) if kind=='val_generations' else (1,50,100)):
