        n=len(rows)
        c=sum(ok(r['output'],r['gts']) for r in rows)
        fmt=sum(last_ans(r['output']) is not None for r in rows)
        boxed=sum('boxed' in r['output'] for r in rows)
        junk=sum(run(r['output'])>=30 for r in rows)
        L=sorted(len(r['output']) for r in rows)
        print(kind,step,'n',n,'acc',round(c/n,4),'has####',fmt,'boxed',boxed,'long-char-run',junk,'median_chars',L[n//2],'max_chars',L[-1])
